\begin{tikzpicture}
\begin{axis}[
    width=0.78\textwidth,
    height=0.48\textwidth,
    xmin=-1.35, xmax=1.35,
    ymin=-1.35, ymax=1.35,
    axis lines=middle,
    axis on top,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-1,0,1},
    ytick={-1,0,1},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[domain=-1:0, samples=100, fill=gray!25, draw=none] {x^3} \closedcycle;
\addplot[domain=0:1, samples=100, fill=gray!15, draw=none, fill opacity=0.5] {x^3} \closedcycle;
\addplot[very thick, domain=-1.15:1.15, samples=150] {x^3};
\node[anchor=north] at (axis cs:-0.95,-0.05) {negative};
\node[anchor=south] at (axis cs:0.95,0.05) {positive};
\node[anchor=west] at (axis cs:0.55,0.9) {\(y=x^3\)};
\end{axis}
\end{tikzpicture}

